export class MatchAudio{
 constructor(){this.context=new AudioContext();const buffer=this.context.createBuffer(1,this.context.sampleRate*2,this.context.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.02;const source=this.context.createBufferSource(),filter=this.context.createBiquadFilter();source.buffer=buffer;source.loop=true;filter.type='lowpass';filter.frequency.value=650;this.crowd=this.context.createGain();this.crowd.gain.value=.7;source.connect(filter).connect(this.crowd).connect(this.context.destination);source.start();this.lastKick=-1;this.lastGoals=0;}
 tone(frequency,duration,volume,type='sine'){const at=this.context.currentTime,osc=this.context.createOscillator(),gain=this.context.createGain();osc.type=type;osc.frequency.setValueAtTime(frequency,at);gain.gain.setValueAtTime(volume,at);gain.gain.exponentialRampToValueAtTime(.001,at+duration);osc.connect(gain).connect(this.context.destination);osc.start();osc.stop(at+duration);}
 update(world){if(world.kickAt!==this.lastKick&&world.kickAt>=0){this.lastKick=world.kickAt;this.tone(world.flight?.kind==='SHOT'?90:130,.07,.09,'triangle');}const goals=world.score[0]+world.score[1];if(goals>this.lastGoals){this.lastGoals=goals;const at=this.context.currentTime;this.crowd.gain.setTargetAtTime(2,at,.2);this.crowd.gain.setTargetAtTime(.7,at+1.5,.5);this.tone(1700,.18,.025);}}
 close(){this.context.close();}
}
